<?php declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';require_admin();$s=dbone('SELECT * FROM basic_settings ORDER BY id LIMIT 1')??[];$title='Settings';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$data=[];foreach(['sitename','phone','email','address','currency','currency_sym','registration','login','maintain','email_verification','sms_verification','sending_charge','transcharge','decimal','minwith','withdrawcharge','depositcharge','timezone','about','terms','privacy','policy','mission','vision','goal'] as $c)if(array_key_exists($c,$_POST))$data[$c]=post($c);if($s){$sets=[];$vals=[];foreach($data as $c=>$v){$sets[]="`$c`=?";$vals[]=$v;}$vals[]=$s['id'];if($sets)dbq('UPDATE basic_settings SET '.implode(',',$sets).' WHERE id=?',$vals);}else{$data['created_at']=date('Y-m-d H:i:s');$data['updated_at']=date('Y-m-d H:i:s');dbq('INSERT INTO basic_settings (`'.implode('`,`',array_keys($data)).'`) VALUES ('.implode(',',array_fill(0,count($data),'?')).')',array_values($data));}$s=dbone('SELECT * FROM basic_settings ORDER BY id LIMIT 1');flash('success','Settings saved.');}require __DIR__.'/includes/header.php';?><div class="card"><h1>System Settings</h1><form method="post"><?=csrf_field()?><div class="form-grid"><?php foreach(['sitename','phone','email','address','currency','currency_sym','registration','login','maintain','email_verification','sms_verification','sending_charge','transcharge','decimal','minwith','withdrawcharge','depositcharge','timezone','about','terms','privacy','policy','mission','vision','goal'] as $c):?><div class="field"><label><?=e(ucwords(str_replace('_',' ',$c)))?></label><?php if(in_array($c,['address','about','terms','privacy','policy','mission','vision','goal'])):?><textarea name="<?=e($c)?>"><?=e($s[$c]??'')?></textarea><?php else:?><input name="<?=e($c)?>" value="<?=e($s[$c]??'')?>"><?php endif;?></div><?php endforeach;?></div><br><button class="btn">Save settings</button></form></div><?php require __DIR__.'/includes/footer.php';?>